/** W77-SIST-PARAM PIC 9(05): dos dígitos de tipo de corrida y tres de sistema. */
public record ParametroCorrida(int tipo, int sistema) {
    static ParametroCorrida de(String sistParam) {             // p.ej. "02500"
        return new ParametroCorrida(Integer.parseInt(sistParam.substring(0, 2)),
                                    Integer.parseInt(sistParam.substring(2, 5)));
    }
}

@Component
public class TipoCorridaDecider implements JobExecutionDecider {
    @Override
    public FlowExecutionStatus decide(JobExecution job, StepExecution step) {
        var p = ParametroCorrida.de(job.getJobParameters().getString("sistParam"));
        return switch (p.tipo()) {
            case 1, 2 -> new FlowExecutionStatus("MOVIMIENTOS");
            case 3    -> new FlowExecutionStatus("SALDOS");
            default   -> new FlowExecutionStatus("NADA");      // el fuente no hace nada ni avisa
        };
    }
}

@Bean
Job interfazS015(JobRepository repo, TipoCorridaDecider decider,
                 Step seleccionaMovtos, Step generaMovtos,       // 10030 + 10050
                 Step seleccionaSaldos, Step generaSaldos) {     // 10010 + 10040
    return new JobBuilder("S151P177", repo)
            .start(decider)
              .on("MOVIMIENTOS").to(seleccionaMovtos).next(generaMovtos)
            .from(decider).on("SALDOS").to(seleccionaSaldos).next(generaSaldos)
            .from(decider).on("NADA").end()
            .end().build();
}

@Bean
Step seleccionaMovtos(JobRepository repo, PlatformTransactionManager tx,
                      FlatFileItemReader<RegistroLog151> log151,
                      SeleccionMovimientosProcessor seleccion) {
    return new StepBuilder("seleccionaMovtos", repo)
            .<RegistroLog151, RegistroLog151>chunk(1000, tx)
            .reader(log151)
            .processor(seleccion)                       // 200-050 + 200-060
            .writer(movs151Writer())
            .listener(new ValidaHeaderLog151())         // SIN HEADER / VACIO: aviso 020101, no aborta
            .build();
}

/** SORT SMOVS151 ON ASCENDING KEY KEY-CONTRATO (KEY-SUCPROM está comentado). */
@Bean
Step ordenaMovtos(JobRepository repo, PlatformTransactionManager tx) {
    return new StepBuilder("ordenaMovtos", repo)
            .tasklet(new SortTasklet<>(movs151(), Comparator.comparing(RegistroLog151::contrato)), tx)
            .build();
    // MEMORY SIZE / DISK SIZE de 70000-CALCULA-ESPACIO dejan de existir: el sort externo es del runtime
}

class ValidaHeaderLog151 implements StepExecutionListener {
    @Override
    public ExitStatus afterStep(StepExecution s) {
        if (s.getReadCount() == 0)      log.info("I 020101 ARCHIVO DE MOVTOS SIN HEADER");
        else if (s.getReadCount() == 1) log.info("I 020101 ARCHIVO VACIO DE MOVTOS");
        return s.getExitStatus();       // mismo comportamiento: el proceso continúa
    }
}

