  umbral-proceso-lote: 20               # TIPO-PROC < 20 es línea; > 19 es lote
  teleton:
    sistema: 500
    procesos-excluidos: [40, 41, 42, 43]

// ---------------------------------------------------------------------------
@Component
@StepScope
@RequiredArgsConstructor
public class SeleccionMovimientosProcessor implements ItemProcessor<RegistroLog151, RegistroLog151> {

    private final P177Properties props;
    @Value("#{jobParameters['sistParam']}") private String sistParam;

    @Override
    public RegistroLog151 process(RegistroLog151 m) {
        if (m.funcion() == 99) return null;                  // trailer del LOG: fin de lectura
        boolean candidato = m.funcion() == 1 && m.status() == 1
                && (m.origen() == 1 || m.origen() == 3)
                && cumpleCondicionTesofe(m);
        if (!candidato) return null;

        var p = ParametroCorrida.de(sistParam);
        if (p.tipo() == 1) return m.tipoProceso() < props.umbralProcesoLote() ? m : null;
        if (p.tipo() == 2 && m.tipoProceso() >= props.umbralProcesoLote()) {
            boolean excluido = p.sistema() == props.teleton().sistema()
                    && props.teleton().procesosExcluidos().contains(m.tipoProceso());
            return excluido ? null : m;                      // 200-060-FILTRA-MOVS-TELETON
        }
        return null;
    }

    /**
     * Fuente: (ESTACION > 0 OR (ESTACION > 0 AND CTACON = 60 OR 61)).
     * Por precedencia COBOL (AND antes que OR) equivale a ESTACION > 0 OR CTACON = 61.
     * Se reproduce tal cual; ver riesgo.
     */
    private static boolean cumpleCondicionTesofe(RegistroLog151 m) {
        return m.estacion() > 0 || m.cuentaContable() == 61;
    }
}

# application.yml   (rangos y claves compilados en GRABA-MOVS)
p177:
  claves-reales:
    minimo-directo: 1000              # CVETRAN > 999
    rangos: [[731, 746], [858, 869]]
    sueltas: [873, 885]
  claves-siempre-edc: [1009, 1072, 3018, 4016]
  envedc-a-estado-cuenta: [2, 3, 4]
  cuentas-tesofe: [60, 61]

// ---------------------------------------------------------------------------
@Component
@StepScope
@RequiredArgsConstructor
public class ExpandeMovimientoProcessor implements ItemProcessor<RegistroLog151, List<RegistroS015>> {

    private final P177Properties props;
    private final CatalogoTransacciones catalogo;   // WKS-T-PARAMETROS-TRANS OCCURS 5000
    private final DatosAdicionales l02;             // 31100-DATADIC
    private final TesofeWriterHelper tesofe;        // GRABA-TESOFE

    @Override
    public List<RegistroS015> process(RegistroLog151 m) {
        var adic = l02.lee(m.apuntadorDatos());
        var salida = new ArrayList<RegistroS015>();
        for (int k = 0; k < 5; k++) {
            ClaveImporte ci = m.claves().get(k);
            if (!props.esClaveReal(ci.clave())) continue;
            int clave4 = Math.toIntExact(ci.clave() % 10_000);       // MOVE 9(06) a 9(04): conserva los 4 dígitos bajos
            var r = RegistroS015.movimiento(m, clave4, ci.importe(), adic, k);
            r = naturaleza.aplica(r);                                 // 31000-NATURALEZA
            r = leyendas.aplica(r, m, adic, k);                       // 31200 + 13300 TaxID
            r = ConversionImporte.aplica(r);                          // 31300: 731-746 llevan importe en la leyenda
            boolean aEdc = props.envedcAEstadoCuenta().contains(catalogo.envedc(clave4))
                    || props.clavesSiempreEdc().contains(clave4);
            if (!aEdc) continue;
            if (props.cuentasTesofe().contains(m.cuentaContable())) salida.addAll(tesofe.registros(r, m));
            else                                                   salida.add(r);
        }
        return salida;                                                // totales en el ItemWriter
    }
}

@Component
@RequiredArgsConstructor
public class NaturalezaContable {

    private final CatalogoTransacciones catalogo;   // WKS-PT-NATURALEZA, catálogo S080

    public RegistroS015.Movimiento aplica(RegistroS015.Movimiento r) {
        int clave = r.claveTransaccion();
        if (clave > 5000)                     return r.conNaturaleza('*', 3);
        if (clave == 1009 || clave == 1072)   return r.conNaturaleza('A', r.naturalezaNum()); // abono forzado
        if (clave == 3009 || clave == 3036)   return r.conNaturaleza('*', r.naturalezaNum());
        int nat = catalogo.naturaleza(clave);
        char alfa = switch (nat) {
            case 1  -> 'C';                   // cargo
            case 2  -> 'A';                   // abono
            default -> '*';
        };
        return r.conNaturaleza(alfa, nat);
    }
}

@Component
public class SeleccionaSaldosProcessor implements ItemProcessor<RegistroSaldos151, RegistroS015.Saldo> {

    static final int TIPO_CUENTA = 81, CONCEPTO_SALDO_ACTUAL = 2, MAX_CONCEPTOS = 30;   // TESOFE 2019: 13 -> 30

    @Override
    public RegistroS015.Saldo process(RegistroSaldos151 s) {
        if (s.tipoRegistro() != TIPO_CUENTA || s.estacion() <= 0) return null;
        return s.conceptos().stream()
                .limit(MAX_CONCEPTOS)
                .filter(c -> c.clave() == CONCEPTO_SALDO_ACTUAL)
                .findFirst()                          // UNTIL W77-SW-ENCONTRE > 0
                .map(c -> new RegistroS015.Saldo(s.estacion(), s.sucursalPromotora(), s.cuenta(),
                        s.producto(), s.instrumento(),
                        c.importe(),                  // S9(13)V99, escala 2
                        s.cuentaContable()))
                .orElse(null);
    }
}

@Component
@RequiredArgsConstructor
public class TesofeWriterHelper {

    private final DatosAdicionales l02;      // L02-DATOS, acceso RANDOM

    /** GRABA-TESOFE: registro con USO-CTA = cuenta contable y, si aplica, el de la subcuenta. */
    public List<RegistroS015> registros(RegistroS015.Movimiento r, RegistroLog151 m) {
        var salida = new ArrayList<RegistroS015>();
        salida.add(r.conUsoCuenta(m.cuentaContable()));          // 60 o 61
        if (m.apuntadorDatos() > 0) {
            Optional<SubcuentaTesofe> sub = l02.leeTesofe(m.apuntadorDatos() + 1);   // INVALID KEY -> vacío
            sub.filter(x -> x.indicador() == 62 || x.indicador() == 63)
               .ifPresent(x -> salida.add(r.conUsoCuenta(x.indicador())
                                           .conContrato(x.contrato())));
        }
        return salida;   // ambos registros suman al trailer con el mismo importe
    }
}

@Component
@RequiredArgsConstructor
public class CatalogoTaxId {

    private final CatalogoS080Client s080;            // L710_CONSUL_LEYENDA IN S080BD01CON
    private final Map<Integer, String> taxIdPorClave = new HashMap<>();   // WKS-POSCI-TAX + WKS-TAX-ID

    @PostConstruct
    void carga() {
        var pagina = s080.consultaLeyenda(151, 20, LlaveS080.inicio());  // clave 20, 10 registros por llamada
        while (true) {
            if (pagina.resultado() > 1) {
                throw new IllegalStateException("ERROR EN CALL PARAMETROS S080BD01CON");  // 020901
            }
            for (var reg : pagina.registros()) {
                int clave = reg.llave3();
                if (clave > 0 && clave < 9999) taxIdPorClave.put(clave, reg.llave1());
                else log.warn("LA CLAVE DE TRANSACION ESTA MAL: {}", clave);
            }
            if (pagina.resultado() == 0) break;           // 0 = última página, 1 = hay más
            pagina = s080.consultaLeyenda(151, 20, pagina.ultimaLlave());
        }
    }

    /** 13300-LEYENDAS-TAXID: decora la leyenda si la clave tiene TaxID. */
    public Optional<String> taxId(int clave) { return Optional.ofNullable(taxIdPorClave.get(clave)); }
}
